sys_script_include.script:
var RegisterAttendeeUtils = Class.create();
RegisterAttendeeUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	register: function() {
		var firstName = this.getParameter('sysparm_first_name');
		var lastName = this.getParameter('sysparm_last_name');
		var email = this.getParameter('sysparm_email');
		var contact = this.getParameter('sysparm_contact');
		var event_id = this.getParameter('sysparm_event_id');

		var gr = new GlideRecord('x_1790139_event_ma_attendee');
		gr.initialize();
		gr.setValue('x_first_name', firstName);
		gr.setValue('x_last_name', lastName);
		gr.setValue('x_email', email);
		gr.setValue('x_contact_number', contact);
		gr.setValue('x_event_id', event_id);
		gr.insert();

		return "success";
	},
    type: 'RegisterAttendeeUtils'
});
